"""Source-aware rules for a repeatable archive audit; not independent fact verification."""
import re
C=['Open vs. Closed Models','AI Adoption & Workloads','AI Pricing & Profitability','Compute Supply & Demand','Custom Silicon & ASICs','Cloud Capex & Financial Health','Infrastructure Capacity & Constraints']
def has(p,t):return bool(re.search(p,t,re.I))
def branch(name,direction,check,inference,bridge,impact,counter):
 return dict(name=name,direction=direction,label='Source-aware scenario',check=check,inference=inference,bridge=bridge,impact=impact,watch=['Verify original report and exact scope','Measure net workload / capacity change','Confirm incremental orders and fabrication route'],counter=counter)
PICKS=['revolut-cuts-ai-token','samsung-conditions-hbm','amazon-offloads-8b','nvidias-proposed-5b-credit','transformer-lead-times','nvidia-h200-gpu-rental','meta-runs-production-inference','anthropic-details-8954b']
ANGLES={
PICKS[0]:'Cheaper AI can still mean more NVIDIA hardware: separate the customer’s API saving from its self-hosted fleet.',
PICKS[1]:'Memory scarcity may become leverage over foundry share, not merely a shipment bottleneck.',
PICKS[2]:'A chip ownership transfer can preserve compute use; financial engineering is not a chip cancellation.',
PICKS[3]:'A GPU supplier may back the power/building and become landlord on default: follow where credit risk moves.',
PICKS[4]:'Contracted GPUs, operational GPUs and delivered-but-idle GPUs are different quantities.',
PICKS[5]:'Higher older-generation rents can coexist with one major customer exiting incompatible older hardware.',
PICKS[6]:'Open-source software can help workloads leave NVIDIA for TPUs while foundry demand stays with TSMC.',
PICKS[7]:'Commitment timing, cash operating performance and noncash losses tell different stories about procurement risk.'}
def review_story(s,matches):
 t=s['title'];body=s['summary'];text=t+'\n'+body;ids=[m['id'] for m in matches]
 profile='model';reason='Model capability or release is a possible demand input, not evidence of adoption or procurement.';cats=[C[0]];branches=[];caveats=[]
 compute=has(r'\bgpus?\b|\bcpus?\b|\btpus?\b|trainium|\basics?\b|accelerator|\bcompute\b|computing capacity|server processors|\binference\b|torchtpu|torchneuron|maia|ai chips?|h100|h200|b200|b300|blackwell|rubin|vr200|nvl72|gb200|gb300',t)
 infra=has(r'data cent(?:er|re)|\bpower\b|\bgrid\b|transformer lead|turbine|cowos|packaging|\bhbm|semiconductor foundry|samsung.*foundry|tsmc|wafers?|2nm|3nm',t)
 if has(r'voting power|powers? on key matters',t):infra=False
 finance=has(r'financ|fundrais|debt|credit|\bcds\b|capex|cash flow|capital raise|capital scarcity|loans?|lends|total funding|leaseback|\bspv\b|commit.*spend|compute bill',t)
 compute_title=compute
 if (infra or finance) and has(r'\bgpus?\b|\bcpus?\b|\btpus?\b|compute capacity|computing capacity|ai processors|vera rubin|blackwell',body):compute=True
 pricing=has(r'price|pricing|cheaper|lower cost|cost cut|cuts?.*cost|costs? by|costs? \d|token.*cost',t) and not (infra or finance)
 efficiency=has(r'throughput|tokens? per second|tok/s|tok.s|speed|faster|prefill|decod|kernel|cpu.*(cut|drop)|cut.*cpu|reduces?.*compute|compute.*(reduc|fewer)|fewer tokens|token.efficient|efficient.*(architect|attention)|cut.*token use',t)
 usage=has(r'(token|compute|internal use|daily.*usage).*(grew|growth|jump|surge|trillion|billion|tops|increase)|adoption|enterprise revenue|enterprise.*sales',t) and not efficiency
 restriction=has(r'export|sanction|\bbans?\b|restrict|licens|smuggl|tracking|bulk imports',t) and has(r'chip|gpu|model|deepseek|compute|nvidia|china',text)
 # An archive-wide relevance pass admits actual capacity / hardware stories previously missed.
 relevant=bool(ids) or compute or infra or (finance and has(r'ai|cloud|anthropic|openai|neocloud',text))
 if has(r'computer control|desktop computer|computer science|pierre computer|perplexity computer.*rebuild|alleged.*spy|romantic|market cap|top semiconductor pick|chip design test|gpu_mode|fingerprinting',t) and not ids:relevant=False
 if not relevant:return dict(included=False,profile='outside_scope',reason='No sufficiently explicit compute, AI economics or manufacturing transmission identified in this rules-based pass.',categories=[],branches=[],caveats=['Exclusion is preliminary; it is not proof of no TSMC relevance.'])
 def setp(p,r,cs):
  nonlocal profile,reason,cats
  profile=p;reason=r;cats=cs
 if 'C2' in ids:setp('financing','AI investment economics or financial sentiment; confirm a cash or procurement transmission.',[C[5]])
 if 'C3' in ids:setp('pricing','Separate paid usage, throughput, selling prices and customer task costs.',[C[2]])
 if 'C6' in ids:setp('capacity','CPU activity requires an exact processor, workload and fabrication route.',[C[3]])
 if 'foundry' in ids or 'memory' in ids or 'packaging' in ids:setp('infrastructure','Assess the specific manufacturing or memory program, not a generic model release.',[C[6]])
 if 'C5' in ids:setp('asic','Custom-chip program, supplier ecosystem or market outlook; distinguish forecasts from orders.',[C[4],C[3]])
 if infra:setp('infrastructure','Physical infrastructure can alter deployment timing or manufacturing capture.',[C[6]])
 if compute_title:setp('capacity','The reported subject includes compute hardware, capacity, access or procurement.',[C[3]])
 if pricing:setp('pricing','Identify whose price/cost changes and compare the same service, unit and workload.',[C[2]])
 if usage:setp('usage','Reported workload/revenue growth is separate from capacity throughput.',[C[1]])
 if finance:setp('financing','Funding, obligations and cash generation affect the ability to execute compute plans.',[C[5]])
 if has(r'trainium|\btpus?\b|custom.*(chip|silicon)|maia|asic|torchtpu',t):setp('asic','Supplier substitution does not necessarily reduce TSMC manufacturing demand.',[C[4],C[3]])
 if efficiency and not finance and not infra:setp('efficiency','A throughput or compute-per-task improvement is not observed aggregate usage.',[C[3],C[2]])
 if has(r'consumer cpus?|mobile hardware|edge ai|local ai|fully local|on mac|m3 ultra|rtx.*pcs|consumer gpus',t):setp('edge','Work may move from cloud accelerators to client devices; server-CPU expansion is not the default.',[C[3],C[0]])
 if has(r'tokens? per mw|tokens? per watt',t):setp('efficiency','Energy-normalized throughput is not aggregate token usage; test actual power and workload scope.',[C[3],C[2]])
 if has(r'rental|rental rates|gpu.*rates|gpu.*prices|h100.*cost|h200.*cost',t) and not finance:setp('rental','Rental economics refer to a specified hardware generation and contract, not model API prices.',[C[3],C[2]])
 if has(r'leaseback|\bspv\b',t):setp('leaseback','Ownership/financing changes while the reported operator retains use; this is not a hardware-demand cancellation.',[C[5],C[3]])
 if has(r'cut.*cpu|cpu use.*(cut|drop|reduc)|rewrites messages api',t):setp('cpu_efficiency','The source reports reduced API CPU resources at comparable traffic, not increased server demand.',[C[3],C[2]])
 if has(r'self.host',t):setp('self_host','Customer API savings and physical GPU purchases can move in opposite directions.',[C[2],C[3]])
 if has(r'conditions hbm',t):setp('memory_bargain','Reported HBM bargaining could change AMD foundry allocation, with no signed transfer established.',[C[6],C[3]])
 if has(r'oracle.*gas|gas.*oracle',t):setp('operating_cost','Site fuel costs affect operating payback, not model token prices.',[C[6],C[5]])
 if has(r'power costs|electricity.*cost|grid.*cost|operating costs|climate change',t):setp('operating_cost','Electricity or operating expenses are not token selling prices; cost pressure does not establish order cancellation.',[C[6],C[5]])
 if has(r'memory layer|shared memory|context.*memory',t):setp('software_memory','Software context storage is not evidence of HBM supply or physical-memory orders.',[C[1]])
 if has(r'export.*(jump|surge)|economy.*growth.*export',t):setp('macro_exports','Aggregate trade growth does not establish a restriction or a TSMC-specific manufacturing order.',[C[3]])
 if has(r'pcb issues|rack.*delay|volume ramp.*push',t):setp('system_delay','A rack-component delay can defer systems; it is not proof that TSMC wafers were cancelled.',[C[6],C[3]])
 if has(r'scales back rented|declines option.*expand|loses access.*oracle',t):setp('capacity_reallocation','Separate customer-specific compatibility/access from total compute demand and reassignment.',[C[3],C[5]])
 if restriction and profile not in ['macro_exports','capacity_reallocation']:setp('access','Distinguish implemented access restrictions, proposals, licenses and corporate commentary.',[C[3],C[6]] if compute else [C[0],C[6]])
 if has(r'risk report|benchmark bugs|cheating|ownership|ad scandal|paid labels|security flaws|attempted.*upload|deletes local files|foundation model.*bci|bci record|construction ready building models',t):setp('indirect','Safety, benchmark integrity or application news has only an indirect compute transmission without adoption evidence.',[C[0]])
 if has(r'lends|financing|funding shortage|capital scarcity',t) and profile=='asic':setp('financing','This report concerns financing for a chip program; deal execution and procurement are separate milestones.',[C[5],C[4]])
 if compute and C[3] not in cats:cats=(cats+[C[3]])[:2]
 if pricing and profile=='model':cats=[C[2],C[0]]
 if profile=='model' and has(r'model|weights|gemini|claude|gpt|glm|kimi|qwen|deepseek|llama|gemma|nano banana',t):cats=[C[0]]
 # Topic corrections apply independently of open-weight status or scenario direction.
 if has(r'cost|price',t) and profile=='model':cats=[C[2],C[0]]
 up='Additional orders benefit TSMC only where the exact chip program is fabricated or packaged there. Confirm the node, package and order timing.'
 net='Net TSMC demand remains unresolved; distinguish total system demand, supplier share, manufacturing content and delivery timing.'
 if profile in ['efficiency','cpu_efficiency','edge','software_memory','indirect','macro_exports','operating_cost','leaseback','system_delay','self_host','memory_bargain','capacity_reallocation','capacity','usage','rental','financing','asic','access']:
  if profile=='self_host':
   named='56 NVIDIA B200 GPUs (reported)' if has(r'56',body) and has(r'b200',body) else 'Self-hosted hardware (verify supplier)'
   branches=[branch('Self-hosting creates hardware demand','up','Verify deployed versus newly purchased GPUs, exact GLM version/license, paid API displacement and subsequent workload growth.','The customer may spend less on frontier APIs while buying/using its own GPU fleet; removing token rationing can expand tasks.',named+' → NVIDIA → TSMC (verify manufacturing)','The reported fleet is a hardware link, not proof of another future order. Additional deployments could support TSMC.','Existing hardware or lower compute per task may absorb growth.'),branch('Frontier API displacement','mixed','Separate the customer’s saving from OpenAI/Anthropic revenue lost, and test whether their freed capacity is reused.','Traffic shifts between hosted labs and self-hosting; displaced lab workloads need not reduce global GPU demand.','Customer GPUs ↔ displaced hosted capacity',net,'Self-hosted demand may outweigh the displaced API workload.')]
  elif profile in ['efficiency','cpu_efficiency','edge','software_memory']:
   target='CPU resources' if profile=='cpu_efficiency' else 'cloud compute' if profile=='edge' else 'compute per comparable task'
   branches=[branch('Efficiency / location offset','mixed','Confirm equal-quality tasks, batch size, latency, hardware, energy and actual production scope. Tokens/second is capacity, not consumed tokens.','The report may reduce '+target+' or move execution to client devices; it does not by itself show lower paid usage.','Workload × resources per task × cloud/client allocation',net,'Cheaper tasks may expand workload volume enough to offset savings.'),branch('Lower cost unlocks usage','up','Find actual additional paid tasks and new hardware orders; distinguish benchmarks from deployed results.','Improved economics may expand training/inference beyond existing capacity.','Verified GPU / CPU / ASIC supplier → TSMC',up,'Usage can fit in spare capacity; client-device gains do not establish server CPU demand.')]
  elif profile=='memory_bargain':
   branches=[branch('Memory leverage shifts foundry share','down','Verify whether AMD accepts a production allocation, exact program/node and whether any TSMC orders are displaced.','If HBM access is tied to a qualified Samsung foundry award, part of AMD manufacturing could move away from TSMC.','Samsung HBM bargaining → AMD foundry allocation → TSMC share','Conditional share downside; negotiations alone establish no lost TSMC wafers.','AMD may reject the terms or source HBM elsewhere.'),branch('Alternative supply preserves output','up','Check alternative HBM qualification and unchanged TSMC allocation.','Securing memory without shifting logic fabrication can enable AMD system shipments.','Qualified HBM → AMD accelerators → TSMC',up,'Qualification and supply timing can still constrain shipments.')]
  elif profile=='leaseback':
   branches=[branch('Financing preserves hardware use','mixed','Confirm deal completion, assets already installed, lease terms and use of proceeds.','A sale-and-leaseback changes ownership and financing while hardware can remain in service.','Operator → asset vehicle / lessor → retained GPU use',net,'Released cash may fund expansion, but that needs separate procurement evidence.'),branch('Funding economics constrain expansion','down','Check lease payments, residual-value allocation and new funding capacity; do not infer distress from the structure alone.','If financing costs or collateral risks impair returns, the operator may reduce subsequent expansion.','Financing cost → future chip orders → TSMC','Possible future-order downside; no cancellation of the existing fleet is established.','A well-priced structure may improve liquidity and sustain expansion.')]
  elif profile in ['system_delay','operating_cost']:
   branches=[branch('Timing / operating-cost pressure','down','Verify site/component, incremental cost, delivery acceptance and actual procurement revisions. A power-price increase is not necessarily a power shortage.','Higher operating expense or incomplete systems can weaken payback or delay delivery, without eliminating lifetime compute demand.','System readiness / economics → procurement timing → TSMC','Potential margin or shipment-timing downside; separate TSMC wafer sales from downstream system revenue.','Contracts, inventory or alternative sites/suppliers can preserve orders.'),branch('Mitigation preserves deployment','mixed','Check qualified substitutes, energy contracts, rescheduling and relocation.','Mitigation may preserve hardware purchases while changing timing or economics.','Alternative deployment → GPU / ASIC / CPU systems',net,'Mitigation has costs and can still delay revenue.')]
  elif profile=='capacity_reallocation':
   branches=[branch('Customer-specific capacity exit','down','Verify affected generation, contractual scope and replacement tenants; do not extrapolate one customer to all compute.','Unfilled capacity may weaken the operator’s cash flow and reduce follow-on purchases.','Cloud customer → operator → GPU / ASIC supplier → TSMC','Possible order downside only if capacity is not reassigned and procurement changes.','Other tenants may still want the released hardware.'),branch('Credit → connected projects','down','Verify actual financing deterioration and program-specific obligations. A graph edge is not contagion.','Funding pressure could defer connected deployments if obligations cannot be funded.','Operator / financing counterparties → projects → chip orders','Conditional timing downside to TSMC-linked manufacturing.','New funding or strong customer cash flows can preserve procurement.'),branch('Upgrade or reassignment preserves demand','mixed','Track replacement systems, tenant reassignment and global workload relocation.','A customer can leave older hardware while buying newer compute elsewhere; another tenant may use the old fleet.','Released capacity / replacement GPU generation → total orders',net,'Reassignment may take time and may use already-produced hardware.')]
  elif profile=='rental':
   branches=[branch('Scarcity supports fleet economics','up','Confirm exact GPU generation, realized comparable rental terms, utilization and whether power or chip supply is binding.','Higher realized rents can signal wanted capacity and improve expansion economics; this applies to the named generation, not automatically older H100/A100.','Generation-specific rentals → funded incremental GPU orders → TSMC',up,'A power bottleneck or a small quote sample can raise rent without new wafer demand.'),branch('Existing fleet absorbs demand','mixed','Check renewals, resale versus new chips, available power and replacement schedules.','Strong old-fleet demand can extend useful life or delay replacement; lower rents may also reflect efficiency or new supply.','Fleet utilization / useful life → future replacement orders',net,'Expansion and longer retention can occur together.')]
  elif profile=='financing':
   branches=[branch('Funding supports execution','up','Separate proposals from closed financing, cash from noncash losses, multi-year commitments from near-term payments, and guarantees from chip orders.','Available funding can preserve or expand compute procurement when sites and contracts are executable.','Financier / customer → cloud or chip program → TSMC',up,'Funding can refinance existing assets rather than buy new chips.'),branch('Cash or delivery obligations constrain orders','down','Match cash maturities, funding commitments, lease cancellation rights and actual hardware deferrals. Do not equate stock declines or accounting losses with cash distress.','If financing gaps or delivery penalties exceed available liquidity, projects may be deferred.','Cash-flow / credit constraint → verified procurement changes','Potential TSMC order-timing downside, conditional on project and manufacturing exposure.','Fresh capital, customer advances or long-dated obligations can reduce near-term pressure.')]
  elif profile=='asic':
   branches=[branch('GPU / ASIC mix shifts','mixed','Confirm software deployment versus future plans, chip generation, foundry allocation and packaging.','Easier migration or external ASIC sales may shift workloads away from GPUs while keeping fabrication at TSMC.','NVIDIA GPUs ↔ TPU / Trainium / custom ASIC → verified foundry',net,'A rival accelerator can be fabricated elsewhere; software support alone is not silicon volume.'),branch('New capacity expands total compute','up','Identify orders for additional systems beyond displaced GPU capacity; distinguish announcement, qualification and shipments.','A successful ASIC platform can unlock additional cost-effective workloads and hardware demand.','Verified ASIC manufacturing program → TSMC',up,'External chip sales may reallocate the same wafer capacity instead of expanding it.')]
  elif profile=='access':
   branches=[branch('Access limits eligible demand','down','Confirm proposal versus effective rule, jurisdiction, chip/model version and enforcement. A license or political statement is not a shipment.','Restricted customers may lose access or defer deployments.','Eligible market → hardware supplier → TSMC','Possible affected-order downside; distinguish existing hardware from unplaced wafer orders.','Capacity can move to approved customers or markets.'),branch('Approved demand or reassignment','mixed','Verify approved licenses, replacement tenants and funded deployment.','Licensing or reallocation may preserve demand and alter geographic mix.','Approved customer → GPU / ASIC allocation',net,'Approval alone does not establish incremental orders.')]
  elif profile=='usage':
   branches=[branch('Workload expansion needs compute','up','Verify absolute paid tasks/tokens, period, platform coverage and whether internal usage is subsidized. Revenue is not a physical workload measure.','If actual workloads grow faster than efficiency and spare capacity, new hardware may be needed.','Model / enterprise workload → verified GPU / ASIC / CPU supplier → TSMC',up,'Platform share, internal experimentation or cheaper tasks may inflate measured growth without equivalent chip demand.'),branch('Efficiency and redistribution offset','mixed','Compare total tasks across providers, compute per task and existing utilization.','Growth on one platform may be redistributed traffic or fit existing hardware.','Net tasks × compute intensity → incremental capacity',net,'Sustained workload growth can eventually exhaust spare capacity.')]
  elif profile=='capacity':
   branches=[branch('Capacity converts to orders','up','Identify delivered versus contracted versus proposed hardware, GPU/CPU generation, funding, power and acceptance.','Executable new capacity can generate incremental hardware purchases.','Named compute supplier → verified TSMC fabrication / packaging',up,'A capacity commitment, repurposed chip or already-installed fleet is not a fresh wafer order.'),branch('Execution or utilization offset','mixed','Check build schedule, existing inventory, customer utilization and competing supplier allocation.','Deployment may be delayed or use existing assets rather than new production.','Installed / committed / operational capacity reconciliation',net,'Signed delivery milestones and energized sites can support conversion.')]
  elif profile in ['indirect','software_memory','macro_exports']:
   branches=[branch('Indirect signal requires a bridge','mixed','Verify the reported event and identify actual workload, hardware or manufacturing allocation affected.','This story does not directly establish a change in chip procurement.','Reported event → missing workload / hardware evidence → TSMC',net,'A later adoption or production disclosure could establish a stronger link.'),branch('Follow-on adoption or allocation','up','Look for subsequent production use or program-specific purchase evidence.','If the event drives additional verified compute or manufacturing demand, TSMC may capture part.','Verified follow-on program → TSMC',up,'Attention, aggregate exports or software features alone are insufficient.')]
 if profile=='infrastructure' and not branches and s.get('primaryLens') not in ['memory','packaging','foundry','deployment'] and not any(i in ids for i in ['memory','packaging','foundry','deployment']):
  branches=[branch('Infrastructure readiness','mixed','Check the actual site, physical component, financing, power connection and operational milestones.','Infrastructure announcements may enable compute but construction, available power and hardware delivery have different schedules.','Qualified site / physical supply → deployed compute → chip orders',net,'Installed capacity and policy promises may not convert to procurement.'),branch('Constraint delays shipment conversion','down','Find a documented delay, cancelled allocation or delivery deferral rather than extrapolating from a headline.','A binding infrastructure constraint can delay systems even if long-run chip demand remains.','Bottleneck → system timing → TSMC exposure','Conditional shipment or order-timing downside.','Alternative sites, suppliers and inventory can absorb the constraint.')]
 if has(r'denies reports.*memory',t):
  profile='denial';reason='The denial limits the earlier expansion narrative; it is not a new memory business or a lost foundry order.';cats=[C[6]]
  branches=[branch('Expansion claim not established','mixed','Read the denial against the original claim; distinguish logic base dies from DRAM manufacturing.','Do not add speculative memory-fab revenue to the TSMC chain.','Company denial → revised manufacturing assumptions',net,'Existing logic and packaging programs may remain unchanged.'),branch('Existing exposure remains','mixed','Verify current logic / packaging allocations separately.','A denial of one activity does not settle demand for other programs.','Verified existing chip programs → TSMC',net,'Program-level evidence can establish a separate demand effect.')]
 if branches and has(r'nvidia|h100|h200|b200|b300|rubin|blackwell',t) and profile in ['capacity','efficiency']:
  for br in branches:br['bridge']='NVIDIA (named in report) → '+br['bridge']
 for br in branches:
  if 'TSMC' not in br['bridge']:br['bridge']+=' → conditional TSMC exposure'
 if has(r'huawei hardware|ascend',t):
  caveats.append('The report names Huawei/Ascend. NVIDIA demand and TSMC fabrication are not established by an open-model story.')
  for br in branches:br['bridge']='Reported Huawei/Ascend program → foundry allocation unestablished'
 if s.get('pricingContext'):
  profile='service_efficiency';reason='The source explicitly attributes service-price cuts to efficiency, not model-publisher distress.';cats=[C[2],C[0]];branches=[]
 # Always expose economic ambiguity, weak sourcing and historical limits.
 caveats.append('Rules-based source review; original claims and numerical figures have not been independently verified.')
 if not any(tw['role'] in ['source','support'] for tw in s['selectedTweets']):caveats.append('Returned posts are commentary/analysis only; inspect the underlying primary report.')
 if has(r'will|plans|propos|targets|estimat|forecast|negotiat|in talks',t):caveats.append('Forward-looking or proposed; do not count as completed deployment or revenue.')
 if has(r'tokens per|tokens a second|tok/s|tok.s|throughput|prefill',t):caveats.append('Throughput is a hardware/software rate, not aggregate token consumption.')
 if profile=='model':caveats.append('Model release, benchmark gain and attention do not independently establish adoption or NVIDIA orders.')
 return dict(shortlisted=any(s['slug'].startswith(p) for p in PICKS),interestingAngle=next((ANGLES[p] for p in PICKS if s['slug'].startswith(p)),None),shortlistRank=next((i for i,p in enumerate(PICKS) if s['slug'].startswith(p)),99),included=True,profile=profile,reason=reason,categories=list(dict.fromkeys(cats))[:2],branches=branches,caveats=caveats)
